local spec = {
  status = function()
    if not running then
      return {
        state            = has_binding() and "stopped" or "no ces.hyle (needs --hyle node)",
        configured_chain = cfg.chain_id or "hylenet",
        last_error       = last_err or "",
      }
    end
    local i = ces.hyle.info()
    return {
      state       = "running",
      chain       = i.chain_id,
      height      = string.format("%d", i.height),
      accounts    = string.format("%d", i.accounts),
      entries     = string.format("%d", i.entries),
      txs         = string.format("%d", i.txs),
      mempool     = string.format("%d", i.mempool),
      validators  = string.format("%d", i.validators),
      quorum      = string.format("%d", i.quorum),
      sudo_pending = string.format("%d", i.sudo_pending),
      sudo_minted = string.format("%d", i.sudo_minted),
      balance     = string.format("%d", i.balance),
      last_block  = string.format("%d", i.last_block_time),
      app_hash    = hex(i.app_hash),
      self        = hex(i.self),
    }
  end,

  commands = {
    { id = "start", label = "Start chain" },
    { id = "stop",  label = "Stop chain"  },
  },
  on_command = function(id)
    if id == "start" then return do_start()
    elseif id == "stop" then return do_stop() end
    return "unknown command: " .. tostring(id)
  end,

  -- Autostart cannot happen at load time: the host queues the /s/hylenet.conf push at
  -- REGISTER and the child only dispatches it once the run loop is pumping, so starting
  -- before then boots the chain on defaults and quietly ignores the operator's genesis.
  -- Start when the config lands instead. If there is no conf file the host pushes nothing
  -- and this never fires, so a short deferred fallback below covers that case; whichever
  -- gets there first is the only one that runs.
  config_defaults = table.concat({
    "# HyleNet: a multi-node hyle chain. The validator identity is this CES SERVER's key, and",
    "# consensus rides the CES server peer mesh, so this node must be a mutual CES peer of the",
    "# other validators. Ship the SAME config (chain_id, validators, economy) to every node.",
    "chain_id = hylenet",
    "# the validator set: space-separated 64-hex CES server pubkeys, INCLUDING this node's own.",
    "validators =",
    "block_pace_ms = 1000",
    "# a consensus round with NO message activity for this long delivers a timeout and moves on.",
    "# WAN-safe default; must exceed a few inter-validator round-trips or rounds change prematurely.",
    "consensus_timeout_ms = 1000",
    "# 1 = boot the chain when the extension loads (needs validators set + the peers linked)",
    "autostart = 1",
    "# funding is per-block validator autofill (through consensus). ceiling 0 = off.",
    "credit_autofill_ceiling = 0",
    "refill_rate = 0",
    "# economy. With rent on, the chain rejects a genesis where rip_bounty > min(fee_transfer,",
    "# fee_entry): a bounty worth more than the fee to create a rippable entry mints money out",
    "# of the cull.",
    "fee_transfer = 10",
    "fee_entry = 10",
    "# per-op fee for a sudo propose/approve",
    "fee_sudo = 1",
    "rent_rate = 1",
    "rip_bounty = 10",
    "# validator-set bounds -- consensus rules, all nodes must agree.",
    "member_cap = 21",
    "member_floor = 1",
    "# hard ceiling on total state RAM in bytes; 0 = unbounded. A full chain refuses new",
    "# entries and new accounts (existing entries still update; rip frees space).",
    "max_state_bytes = 0",
    "# a pending sudo proposal past this age cannot execute and is cleared. 0 = never.",
    "sudo_ttl_secs = 0",
    "snapshot_interval = 0",
    "block_retention = 1024",
    "",
  }, "\n"),
  on_config = function(c)
    cfg = c
    maybe_autostart()
  end,
}

if mene then spec.panel = build_panel() end
ces.extension_admin(spec)

ces.spawn(function()
  ces.sleep(250)
  maybe_autostart()
end)

-- Paid purchase over the compute CALL verb: sell the caller `value` hyle from the
-- validator balance with a max transfer (never fails on a shortfall), 1:1. The
-- payer key is its hyle account (one key, two ledgers). Reply: the caller's hyle
-- balance after settlement.
function on_l2call(memo, ctx)
  if not (has_binding() and running) then return "err no_chain" end
  if not ctx.payer or #ctx.payer ~= 32 then return "err bad_payer" end
  -- Submit the sale into the mempool and return the tx id. We do not wait on consensus:
  -- the buyer polls `account <yourkey>` (or `txr <id>`) to see when the credit lands.
  local ids, err = ces.hyle.submit(ces.hyle.op.transfer{ to = ctx.payer, amount = ctx.value, max = true })
  if not ids then return "err " .. tostring(err) end
  return "ok " .. hex(ids[1])
end

serve()
ces.run()

end

CES_MANIFEST = { name = "HyleNet", version = "0.1", description = "A multi-node hyle-services blockchain hosted inside cesluajitd over the ces.hyle binding. The validator identity is the CES SERVER key (one key, two ledgers) and consensus rides the CES server peer mesh, so the validator set is the CES servers that are mutual peers and carry the same genesis (chain_id, validators, economy). No transport of its own. Funding is per-block validator autofill. Serves the same ces.conn line protocol as HyleSolo: clients sign their own ops and submit them as opaque bytes. Requires a cesluajitd built with --hyle on an ed25519 server key." }
return require("main")
